import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const packageRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const check = process.argv.includes("--check");
const distOnly = process.argv.includes("--dist");

const compiledClientPath = resolve(packageRoot, "dist/studio/run-store-ui-client.js");
const sourceModulePath = resolve(packageRoot, "src/studio/run-store-ui-client-source.ts");
const distSourcePath = resolve(packageRoot, "dist/studio/run-store-ui-client-source.js");
const distSourceMapPath = `${distSourcePath}.map`;
const distDeclarationPath = resolve(packageRoot, "dist/studio/run-store-ui-client-source.d.ts");

function formatWithOxfmt(contents, filepath) {
  const result = spawnSync("oxfmt", ["--stdin-filepath", filepath], {
    cwd: packageRoot,
    encoding: "utf8",
    input: contents,
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`oxfmt failed for ${filepath}: ${result.stderr}`);
  }
  return result.stdout;
}

const ALLOWED_CLIENT_EXPORTS = new Set(["createStudioRunIndex", "initStudio"]);

function exportedNamesFromLine(line) {
  const fn = /^export function ([A-Za-z_$][\w$]*)\b/.exec(line);
  if (fn) return [fn[1]];
  const named = /^export \{([^}]+)\};?\s*$/.exec(line);
  if (!named) return null;
  const names = [];
  for (const part of named[1].split(",")) {
    const name = part.trim();
    if (!name || !/^[A-Za-z_$][\w$]*$/.test(name)) return null;
    names.push(name);
  }
  return names;
}

/** Strip module syntax from tsc output so the client can run as an inline script. */
export function compiledClientSource(js) {
  const withoutMaps = js.replace(/^\uFEFF?\/\/# sourceMappingURL=.*\r?\n?/gm, "");
  if (/\bimport\s*(?:type\s+)?["'{*]/.test(withoutMaps) || /\bimport\s*\(/.test(withoutMaps)) {
    throw new Error("Compiled studio client still contains import; cannot inline.");
  }
  const exportLines = [...withoutMaps.matchAll(/^export .*$/gm)].map((match) => match[0]);
  const exported = [];
  for (const line of exportLines) {
    const names = exportedNamesFromLine(line);
    if (!names || names.length === 0) {
      throw new Error("Compiled studio client still contains export; cannot inline.");
    }
    exported.push(...names);
  }
  const unique = new Set(exported);
  if (
    exported.filter((name) => name === "initStudio").length !== 1 ||
    unique.size !== exported.length ||
    [...unique].some((name) => !ALLOWED_CLIENT_EXPORTS.has(name))
  ) {
    throw new Error("Compiled studio client still contains export; cannot inline.");
  }
  const stripped = withoutMaps.replace(/^export \{[^}]+\};?\s*\n?/gm, "").replace(/^export /gm, "");
  let source = stripped.replace(/\s+$/u, "");
  if (!/\ninitStudio\(\);\s*$/.test(source)) source += "\ninitStudio();";
  return `${source}\n`;
}

function generatedTypeScript(source) {
  return `/**
 * Compiled studio browser client, generated by scripts/generate-studio-client.mjs.
 * Do not edit. Source of truth: src/studio/run-store-ui-client.ts
 */
export const PIPELINE_RUN_STUDIO_CLIENT_SOURCE = ${JSON.stringify(source)};
`;
}

function generatedJavascript(source) {
  return `export const PIPELINE_RUN_STUDIO_CLIENT_SOURCE = ${JSON.stringify(source)};
`;
}

function generatedDeclaration() {
  return `export declare const PIPELINE_RUN_STUDIO_CLIENT_SOURCE: string;
`;
}

const isMain =
  process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (isMain) {
  if (!existsSync(compiledClientPath)) {
    throw new Error(
      "Build tubeless before generating its studio client: missing dist/studio/run-store-ui-client.js"
    );
  }
  const source = compiledClientSource(readFileSync(compiledClientPath, "utf8"));
  const typeScript = formatWithOxfmt(generatedTypeScript(source), sourceModulePath);
  const javascript = generatedJavascript(source);
  const declaration = generatedDeclaration();

  if (check) {
    const actual = existsSync(sourceModulePath)
      ? readFileSync(sourceModulePath, "utf8")
      : undefined;
    if (actual !== typeScript) {
      throw new Error(
        `Generated ${relative(packageRoot, sourceModulePath)} is stale. Run: bun run studio:generate`
      );
    }
  } else {
    if (!distOnly) {
      writeFileSync(sourceModulePath, typeScript);
      process.stdout.write(`Generated ${relative(packageRoot, sourceModulePath)}\n`);
    }
    mkdirSync(dirname(distSourcePath), { recursive: true });
    writeFileSync(distSourcePath, javascript);
    writeFileSync(distDeclarationPath, declaration);
    // The generated JavaScript replaces the tsc emit and carries no
    // sourceMappingURL, so the tsc-emitted map would be orphaned and misaligned.
    rmSync(distSourceMapPath, { force: true });
    process.stdout.write(`Generated ${relative(packageRoot, distSourcePath)}\n`);
  }
}
